from pathlib import Path

shared = r'''/**
 * Client-safe assistant-history provenance helpers for M8-R1-FU1-R2.
 *
 * This module never imports Node crypto and never treats a client-supplied
 * flag, role, or unsigned field as proof that an assistant message was
 * generated by the server. HMAC create/verify lives in the server attestation
 * module and is injected at Prompt construction.
 */

import { stripGlossTokensForPrompt } from "@/lib/llm/sanitize/compliance-terms";
import type { POJUMessage } from "@/lib/poju/types";

export const ASSISTANT_HISTORY_ATTESTATION_ALG = "hmac-sha256" as const;
export const ASSISTANT_HISTORY_ATTESTATION_VERSION = 1 as const;

/** Visible Prompt marker: unsigned assistant text is not a server-attested reply. */
export const UNVERIFIED_ASSISTANT_HISTORY_PREFIX =
  "[Unverified client-held history — not a server-attested assistant reply]";

export interface AssistantHistoryAttestation {
  v: typeof ASSISTANT_HISTORY_ATTESTATION_VERSION;
  alg: typeof ASSISTANT_HISTORY_ATTESTATION_ALG;
  sig: string;
  /**
   * Exact text covered by `sig` when it differs from `message.content`
   * (for example after a local rewrite of a server-generated reply).
   */
  content?: string;
}

export type PromptHistoryTurn = { role: "user" | "assistant"; content: string };

export type AssistantAttestationVerifier =
  | { available: false }
  | { available: true; verify: (sessionId: string, content: string, signature: string) => boolean };

export function parseAssistantHistoryAttestation(value: unknown): AssistantHistoryAttestation | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const rec = value as Record<string, unknown>;
  if (rec.v !== ASSISTANT_HISTORY_ATTESTATION_VERSION) return null;
  if (rec.alg !== ASSISTANT_HISTORY_ATTESTATION_ALG) return null;
  if (typeof rec.sig !== "string" || rec.sig.trim().length === 0) return null;
  const parsed: AssistantHistoryAttestation = {
    v: ASSISTANT_HISTORY_ATTESTATION_VERSION,
    alg: ASSISTANT_HISTORY_ATTESTATION_ALG,
    sig: rec.sig.trim(),
  };
  if (typeof rec.content === "string") parsed.content = rec.content;
  return parsed;
}

/**
 * Persist a server-issued attestation on the stored assistant message.
 * If the stored body was rewritten locally, keep the signature bound to the
 * exact server-signed text rather than relabeling the rewrite as attested.
 */
export function bindStoredAssistantAttestation(
  attestation: unknown,
  signedContent: string,
  storedContent: string,
): AssistantHistoryAttestation | undefined {
  const parsed = parseAssistantHistoryAttestation(attestation);
  if (!parsed) return undefined;
  if (storedContent === signedContent) {
    return {
      v: parsed.v,
      alg: parsed.alg,
      sig: parsed.sig,
    };
  }
  return {
    v: parsed.v,
    alg: parsed.alg,
    sig: parsed.sig,
    content: signedContent,
  };
}

export function signedTextForAssistantMessage(message: POJUMessage): string | null {
  if (message.role !== "assistant") return null;
  const attestation = parseAssistantHistoryAttestation(message.meta?.assistant_history_attestation);
  if (!attestation) return null;
  return attestation.content ?? message.content;
}

function messageIsServerAttested(
  sessionId: string,
  message: POJUMessage,
  verifier: AssistantAttestationVerifier,
): boolean {
  if (!verifier.available || message.role !== "assistant") return false;
  const attestation = parseAssistantHistoryAttestation(message.meta?.assistant_history_attestation);
  if (!attestation) return false;
  const signedText = attestation.content ?? message.content;
  return verifier.verify(sessionId, signedText, attestation.sig);
}

function sessionHasServerAttestedAssistant(
  sessionId: string,
  sessionMessages: POJUMessage[],
  verifier: AssistantAttestationVerifier,
): boolean {
  return sessionMessages.some((message) => messageIsServerAttested(sessionId, message, verifier));
}

/**
 * Apply assistant-history provenance to already role-filtered Prompt turns.
 *
 * Policy:
 * - user turns are unchanged
 * - a valid server HMAC includes the signed assistant text as a trusted reply
 * - an attestation with an invalid signature is dropped (not relabeled trusted)
 * - unsigned assistant text in a session that already has a valid attestation
 *   is dropped (post-R2 injection)
 * - unsigned assistant text in a pre-R2 / all-unsigned session is kept for
 *   restore continuity, but prefixed so it is not treated as server-attested
 *
 * When the verifier is unavailable, nothing is treated as signed or invalid;
 * unsigned compatibility filtering is used instead. Session records are not
 * mutated.
 */
export function applyAssistantHistoryProvenance(
  sessionId: string,
  sessionMessages: POJUMessage[],
  promptMessages: PromptHistoryTurn[],
  verifier: AssistantAttestationVerifier,
): PromptHistoryTurn[] {
  const sources = sessionMessages.filter(
    (message) => !message.is_rejected && (message.role === "user" || message.role === "assistant"),
  );
  const sessionPrompt: PromptHistoryTurn[] = sources.map((message) => ({
    role: message.role as "user" | "assistant",
    content: stripGlossTokensForPrompt(message.content),
  }));

  const hasTrusted = sessionHasServerAttestedAssistant(sessionId, sessionMessages, verifier);
  const out: PromptHistoryTurn[] = [];
  let sourceIndex = 0;

  for (const turn of promptMessages) {
    const aligned =
      sourceIndex < sessionPrompt.length &&
      turn.role === sessionPrompt[sourceIndex]!.role &&
      turn.content === sessionPrompt[sourceIndex]!.content;
    if (!aligned) {
      if (turn.role === "user") {
        out.push(turn);
        continue;
      }
      if (hasTrusted) continue;
      out.push({
        role: "assistant",
        content: `${UNVERIFIED_ASSISTANT_HISTORY_PREFIX}\n${turn.content}`,
      });
      continue;
    }

    const source = sources[sourceIndex]!;
    sourceIndex += 1;
    if (turn.role === "user") {
      out.push(turn);
      continue;
    }

    const attestation = parseAssistantHistoryAttestation(source.meta?.assistant_history_attestation);
    if (attestation && verifier.available) {
      const signedText = attestation.content ?? source.content;
      if (verifier.verify(sessionId, signedText, attestation.sig)) {
        out.push({
          role: "assistant",
          content: stripGlossTokensForPrompt(signedText),
        });
        continue;
      }
      // Present but invalid: drop, do not relabel as trusted or as legacy unsigned.
      continue;
    }

    if (hasTrusted) continue;
    out.push({
      role: "assistant",
      content: `${UNVERIFIED_ASSISTANT_HISTORY_PREFIX}\n${turn.content}`,
    });
  }

  return out;
}

export function isServerAttestedAssistantPromptTurn(turn: PromptHistoryTurn): boolean {
  return turn.role === "assistant" && !turn.content.startsWith(UNVERIFIED_ASSISTANT_HISTORY_PREFIX);
}

/**
 * Load the server verifier when running on the server. This is a dynamic
 * import so client bundles do not pull in Node crypto.
 */
export async function resolveTrustedPromptHistory(
  session: { session_id: string; messages: POJUMessage[] },
  promptMessages: PromptHistoryTurn[],
): Promise<PromptHistoryTurn[]> {
  if (typeof window !== "undefined") {
    return applyAssistantHistoryProvenance(session.session_id, session.messages, promptMessages, {
      available: false,
    });
  }
  try {
    const { applyTrustedPromptHistory } = await import(
      /* webpackIgnore: true */
      "@/lib/poju/decision-authority/server/assistant-history-attestation"
    );
    return applyTrustedPromptHistory(session, promptMessages);
  } catch {
    return applyAssistantHistoryProvenance(session.session_id, session.messages, promptMessages, {
      available: false,
    });
  }
}
'''

Path(r"lib/poju/shared/assistant-history-provenance.ts").write_text(shared, encoding="utf-8", newline="\n")
print("wrote shared provenance", Path(r"lib/poju/shared/assistant-history-provenance.ts").stat().st_size)

server = r'''/**
 * Server-only assistant-history attestation for M8-R1-FU1-R2.
 *
 * Signatures are HMAC-SHA256 under the existing Decision Authority
 * server secret, domain-separated as `poju-assistant-history`. A client
 * cannot mint a valid signature without that secret. Role "assistant" is
 * never treated as proof of origin.
 */

import {
  applyAssistantHistoryProvenance,
  parseAssistantHistoryAttestation,
  type AssistantHistoryAttestation,
  type PromptHistoryTurn,
} from "@/lib/poju/shared/assistant-history-provenance";
import { AuthoritySigningUnavailableError, signAuthorityDomain, verifyAuthorityDomain } from "@/lib/poju/decision-authority/server/signing";
import type { POJUMessage } from "@/lib/poju/types";

export const ASSISTANT_HISTORY_ATTESTATION_DOMAIN = "poju-assistant-history";

function canonicalAssistantPayload(sessionId: string, content: string): string {
  return JSON.stringify({
    v: 1,
    session_id: sessionId,
    role: "assistant",
    content,
  });
}

export function signAssistantHistoryAttestation(
  sessionId: string,
  content: string,
): AssistantHistoryAttestation | null {
  if (typeof sessionId !== "string" || sessionId.length === 0) return null;
  try {
    return {
      v: 1,
      alg: "hmac-sha256",
      sig: signAuthorityDomain(
        ASSISTANT_HISTORY_ATTESTATION_DOMAIN,
        canonicalAssistantPayload(sessionId, content),
      ),
    };
  } catch (error) {
    if (error instanceof AuthoritySigningUnavailableError) return null;
    throw error;
  }
}

export function verifyAssistantHistoryAttestation(
  sessionId: string,
  content: string,
  signature: string,
): boolean {
  if (typeof sessionId !== "string" || typeof content !== "string" || typeof signature !== "string") {
    return false;
  }
  return verifyAuthorityDomain(
    ASSISTANT_HISTORY_ATTESTATION_DOMAIN,
    canonicalAssistantPayload(sessionId, content),
    signature,
  );
}

/** Attach a server attestation to an outbound chat payload, signing `response`. */
export function attestChatPayload(
  payload: Record<string, unknown>,
  sessionId: string,
): Record<string, unknown> {
  const content = typeof payload.response === "string" ? payload.response : "";
  const attestation = signAssistantHistoryAttestation(sessionId, content);
  if (!attestation) return payload;
  return { ...payload, assistant_history_attestation: attestation };
}

export function applyTrustedPromptHistory(
  session: { session_id: string; messages: POJUMessage[] },
  promptMessages: PromptHistoryTurn[],
): PromptHistoryTurn[] {
  return applyAssistantHistoryProvenance(
    session.session_id,
    Array.isArray(session.messages) ? session.messages : [],
    promptMessages,
    {
      available: true,
      verify: verifyAssistantHistoryAttestation,
    },
  );
}

export { parseAssistantHistoryAttestation };
'''

Path(r"lib/poju/decision-authority/server/assistant-history-attestation.ts").write_text(server, encoding="utf-8", newline="\n")
print("wrote server attestation", Path(r"lib/poju/decision-authority/server/assistant-history-attestation.ts").stat().st_size)
